INSERT INTO schools (id, slug, code, name, short_name, type, region_code, city, founded, students, highlight, website, description, scholarships, hidden, is_custom) VALUES
  ('hust', 'dai-hoc-bach-khoa-ha-noi', 'BKA', 'Đại học Bách khoa Hà Nội', 'ĐH Bách khoa Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1956, 35000, 'Top 1 Kỹ thuật & Công nghệ miền Bắc', 'https://hust.edu.vn', 'Trường đại học kỹ thuật đa ngành hàng đầu Việt Nam, thế mạnh vượt trội về CNTT, Khoa học máy tính, Cơ điện tử, Vi mạch bán dẫn và Tự động hóa.', 'Học bổng khuyến khích học tập 10-100% học phí, học bổng tài năng cho thủ khoa, học bổng doanh nghiệp (Samsung, Viettel, FPT, Honda).', false, false),
  ('neu', 'dai-hoc-kinh-te-quoc-dan', 'KHA', 'Đại học Kinh tế Quốc dân', 'ĐH Kinh tế Quốc dân', 'cong-lap', 'bac', 'Hà Nội', 1956, 30000, 'Top 1 khối Kinh tế & Quản trị', 'https://neu.edu.vn', 'Trường đại học trọng điểm quốc gia về kinh tế, quản lý và quản trị kinh doanh; tiên phong chương trình liên kết quốc tế và đào tạo chất lượng cao.', 'Học bổng khuyến khích học tập, Quỹ học bổng Tài năng NEU, học bổng Big4 kiểm toán và các ngân hàng lớn.', false, false),
  ('ftu', 'truong-dai-hoc-ngoai-thuong', 'NTH', 'Trường Đại học Ngoại thương', 'ĐH Ngoại thương', 'cong-lap', 'bac', 'Hà Nội', 1960, 18000, 'Top 1 Kinh tế đối ngoại & Kinh doanh quốc tế', 'https://ftu.edu.vn', 'Cái nôi đào tạo chuyên gia kinh tế đối ngoại, kinh doanh quốc tế, tài chính quốc tế và khởi nghiệp sáng tạo nổi tiếng năng động.', 'Học bổng khuyến khích học tập, học bổng từ hơn 60 tập đoàn đa quốc gia và cựu sinh viên.', false, false),
  ('uet', 'truong-dai-hoc-cong-nghe-dhqghn', 'QHI', 'Trường Đại học Công nghệ – ĐHQGHN', 'ĐH Công nghệ – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 2004, 9500, 'Top 1 Nghiên cứu Công nghệ & AI', 'https://uet.vnu.edu.vn', 'Trường thành viên nòng cốt của ĐHQG Hà Nội về khoa học công nghệ cao, AI, bán dẫn, công nghệ thông tin và robot học.', 'Học bổng tài năng ĐHQGHN, học bổng viện trợ từ Viettel, VNPT, Samsung, LG Display.', false, false),
  ('ussh', 'truong-dai-hoc-khxhnv-dhqghn', 'QHX', 'Trường ĐH Khoa học Xã hội và Nhân văn – ĐHQGHN', 'ĐH KHXH&NV – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 1995, 13000, 'Top 1 Khoa học Xã hội & Nhân văn', 'https://ussh.vnu.edu.vn', 'Trung tâm đào tạo và nghiên cứu hàng đầu về Báo chí, Truyền thông đa phương tiện, Quan hệ công chúng, Tâm lý học, Đông phương học và Ngôn ngữ.', 'Học bổng khuyến khích học tập, học bổng ĐHQGHN, học bổng các tổ chức quốc tế (KOICA, JICA, DAAD).', false, false),
  ('hus', 'truong-dai-hoc-khoa-hoc-tu-nhien-dhqghn', 'QHK', 'Trường ĐH Khoa học Tự nhiên – ĐHQGHN', 'ĐH Khoa học Tự nhiên – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 1956, 11000, 'Cái nôi khoa học cơ bản hàng đầu', 'https://hus.vnu.edu.vn', 'Đào tạo các ngành khoa học cơ bản mũi nhọn: Toán - Tin, Hóa học, Sinh học, Khoa học Môi trường và Hải dương học.', 'Học bổng ươm mầm tài năng khoa học cơ bản ĐHQGHN (miễn học phí + trợ cấp sinh hoạt).', false, false),
  ('ulis', 'truong-dai-hoc-ngoai-ngu-dhqghn', 'QHN', 'Trường ĐH Ngoại ngữ – ĐHQGHN', 'ĐH Ngoại ngữ – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 1955, 10000, 'Hàng đầu đào tạo Ngoại ngữ & Sư phạm Ngoại ngữ', 'https://ulis.vnu.edu.vn', 'Trung tâm đào tạo ngôn ngữ Anh, Trung, Nhật, Hàn, Pháp, Đức và sư phạm ngoại ngữ uy tín số 1 miền Bắc.', 'Học bổng ĐHQGHN, học bổng chính phủ trao đổi sinh viên nước ngoài.', false, false),
  ('ueb', 'truong-dai-hoc-kinh-te-dhqghn', 'QHE', 'Trường ĐH Kinh tế – ĐHQGHN', 'ĐH Kinh tế – ĐHQGHN', 'cong-lap', 'bac', 'Hà Nội', 1974, 8000, 'Quốc tế hóa đào tạo Kinh tế & Tài chính', 'https://ueb.edu.vn', 'Đào tạo cử nhân kinh tế quốc tế, quản trị kinh doanh, tài chính ngân hàng chuẩn quốc tế và liên kết Đại học Troy (Mỹ).', 'Học bổng UEB Pass, học bổng doanh nghiệp quốc tế.', false, false),
  ('hmu', 'truong-dai-hoc-y-ha-noi', 'YHB', 'Trường Đại học Y Hà Nội', 'ĐH Y Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1902, 12500, 'Trường Đại học Y khoa số 1 Việt Nam', 'https://hmu.edu.vn', 'Trường y khoa lâu đời và danh tiếng nhất Việt Nam, đào tạo Bác sĩ Y đa khoa, Răng - Hàm - Mặt, Y học cổ truyền, Kỹ thuật y học.', 'Học bổng khuyến khích học tập và học bổng từ các bệnh viện Trung ương hàng đầu.', false, false),
  ('hup', 'truong-dai-hoc-duoc-ha-noi', 'DKH', 'Trường Đại học Dược Hà Nội', 'ĐH Dược Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1961, 5000, 'Trường Dược học trọng điểm quốc gia', 'https://hup.edu.vn', 'Cơ sở đầu ngành về đào tạo Dược sĩ đại học, Hóa dược, Công nghệ dược phẩm và kiểm nghiệm chất lượng thuốc.', 'Học bổng khuyến khích học tập, học bổng các tập đoàn dược phẩm đa quốc gia (Sanofi, Astra, Dược Hậu Giang).', false, false),
  ('hnue', 'truong-dai-hoc-su-pham-ha-noi', 'SPH', 'Trường Đại học Sư phạm Hà Nội', 'ĐH Sư phạm Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1951, 22000, 'Trường Sư phạm trọng điểm quốc gia', 'https://hnue.edu.vn', 'Đào tạo giáo viên, giảng viên và chuyên gia giáo dục cho mọi cấp học từ Mầm non đến Đại học.', 'Hỗ trợ học phí & sinh hoạt phí theo Nghị định 116/2020 của Chính phủ cho sinh viên ngành sư phạm.', false, false),
  ('huce', 'truong-dai-hoc-xay-dung-ha-noi', 'XDA', 'Trường Đại học Xây dựng Hà Nội', 'ĐH Xây dựng Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1966, 20000, 'Top 1 ngành Xây dựng, Kiến trúc công trình & Hạ tầng', 'https://huce.edu.vn', 'Đào tạo kỹ sư xây dựng dân dụng, cầu đường, công trình thủy, kiến trúc và quản lý dự án xây dựng.', 'Học bổng Đỗ Quốc Sam, học bổng các tập đoàn xây dựng và tổng công ty hạ tầng.', false, false),
  ('hau', 'truong-dai-hoc-kien-truc-ha-noi', 'KTA', 'Trường Đại học Kiến trúc Hà Nội', 'ĐH Kiến trúc Hà Nội', 'cong-lap', 'bac', 'Hà Nội', 1969, 12000, 'Cái nôi đào tạo Kiến trúc sư & Nhà thiết kế', 'https://hau.edu.vn', 'Đào tạo Kiến trúc sư, Quy hoạch đô thị, Thiết kế nội thất, Thiết kế đồ họa và Kỹ thuật công trình.', 'Học bổng khuyến khích học tập, học bổng từ các hội kiến trúc sư và tập đoàn bất động sản.', false, false),
  ('utc', 'truong-dai-hoc-giao-thong-van-tai', 'GHA', 'Trường Đại học Giao thông Vận tải', 'ĐH Giao thông Vận tải', 'cong-lap', 'bac', 'Hà Nội', 1960, 24000, 'Hàng đầu về Giao thông, Logistics & Kỹ thuật', 'https://utc.edu.vn', 'Đào tạo kỹ sư cầu đường, đường sắt đô thị, cơ khí ô tô, logistics và quản lý chuỗi cung ứng.', 'Học bổng khuyến khích học tập và tài trợ từ Bộ Giao thông Vận tải, các tập đoàn hạ tầng giao thông.', false, false),
  ('ptit', 'hoc-vien-cong-nghe-buu-chinh-vien-thong', 'BVH', 'Học viện Công nghệ Bưu chính Viễn thông', 'Học viện Bưu chính Viễn thông', 'cong-lap', 'bac', 'Hà Nội', 1997, 16000, 'Top đầu CNTT, Viễn thông & Truyền thông đa phương tiện', 'https://ptit.edu.vn', 'Trực thuộc Bộ TT&TT; đơn vị đào tạo hàng đầu về Công nghệ thông tin, Trí tuệ nhân tạo, An toàn thông tin, Viễn thông và Thiết kế Multimedia.', 'Học bổng toàn phần tài năng PTIT, học bổng VNPT, MobiFone, Viettel.', false, false),
  ('aof', 'hoc-vien-tai-chinh', 'HTC', 'Học viện Tài chính', 'Học viện Tài chính', 'cong-lap', 'bac', 'Hà Nội', 1963, 20000, 'Cái nôi Tài chính, Kế toán & Kiểm toán', 'https://hvtc.edu.vn', 'Trực thuộc Bộ Tài chính; trường đào tạo số 1 về Tài chính doanh nghiệp, Ngân hàng, Kế toán, Kiểm toán, Thuế và Hải quan.', 'Học bổng khuyến khích học tập, học bổng ACCA, CPA Australia và các công ty chứng khoán.', false, false),
  ('bav', 'hoc-vien-ngan-hang', 'NHH', 'Học viện Ngân hàng', 'Học viện Ngân hàng', 'cong-lap', 'bac', 'Hà Nội', 1961, 18000, 'Top 1 Ngân hàng, Tài chính & Fintech', 'https://hvnh.edu.vn', 'Trực thuộc Ngân hàng Nhà nước Việt Nam; đào tạo chuyên sâu về Ngân hàng số, Fintech, Tài chính và Quản trị kinh doanh.', 'Học bổng Thống đốc Ngân hàng Nhà nước, học bổng Vietcombank, BIDV, VietinBank, Agribank.', false, false),
  ('dav', 'hoc-vien-ngoai-giao', 'HQT', 'Học viện Ngoại giao', 'Học viện Ngoại giao', 'cong-lap', 'bac', 'Hà Nội', 1959, 6000, 'Cái nôi Ngoại giao, Quan hệ quốc tế & Luật quốc tế', 'https://dav.edu.vn', 'Trực thuộc Bộ Ngoại giao; trường đào tạo tinh hoa về Quan hệ quốc tế, Ngoại giao, Luật quốc tế, Truyền thông quốc tế và Kinh tế quốc tế.', 'Học bổng khuyến khích học tập, học bổng từ các đại sứ quán và tổ chức quốc tế.', false, false),
  ('ajc', 'hoc-vien-bao-chi-va-tuyen-truyen', 'HBT', 'Học viện Báo chí và Tuyên truyền', 'Học viện Báo chí', 'cong-lap', 'bac', 'Hà Nội', 1962, 10000, 'Cái nôi Báo chí, Truyền thông & Quan hệ công chúng', 'https://ajc.edu.vn', 'Trường đại học trọng điểm về đào tạo Nhà báo, Biên tập viên, Chuyên viên Quan hệ công chúng (PR), Quảng cáo và Truyền thông đa phương tiện.', 'Học bổng khuyến khích học tập và học bổng từ các cơ quan báo chí, đài truyền hình VTV, VOV.', false, false),
