  ('hcmue', 'truong-dai-hoc-su-pham-tp-ho-chi-minh', 'SPS', 'Trường Đại học Sư phạm TP. Hồ Chí Minh', 'ĐH Sư phạm TP.HCM', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1976, 20000, 'Trường Sư phạm trọng điểm phía Nam', 'https://hcmue.edu.vn', 'Đào tạo giáo viên các cấp, cử nhân Ngôn ngữ Anh/Hàn/Nhật/Trung/Pháp, Tâm lý học giáo dục và Giáo dục Mầm non.', 'Chính sách trợ cấp sinh hoạt phí & học phí 100% ngành sư phạm theo Nghị định 116.', false, false),
  ('nlu', 'truong-dai-hoc-nong-lam-tp-ho-chi-minh', 'NLS', 'Trường Đại học Nông Lâm TP. Hồ Chí Minh', 'ĐH Nông Lâm TP.HCM', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1955, 22000, 'Hàng đầu về Thú y, Nông nghiệp công nghệ cao & Chế biến thực phẩm', 'https://hcmuaf.edu.vn', 'Đào tạo chuyên sâu về Bác sĩ Thú y, Công nghệ thực phẩm, Nông nghiệp công nghệ cao, Lâm nghiệp, Công nghệ sinh học và Quản lý đất đai.', 'Học bổng khuyến khích học tập, học bổng từ các tập đoàn nông nghiệp và dinh dưỡng quốc tế (CP, De Heus, Cargill).', false, false),
  ('hcmulaw', 'truong-dai-hoc-luat-tp-ho-chi-minh', 'LPS', 'Trường Đại học Luật TP. Hồ Chí Minh', 'ĐH Luật TP.HCM', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1996, 14000, 'Trường đào tạo Pháp luật số 1 miền Nam', 'https://hcmulaw.edu.vn', 'Trực thuộc Bộ Giáo dục và Đào tạo; trường trọng điểm đào tạo cán bộ pháp lý, luật sư, chuyên gia tư vấn luật kinh tế và luật quốc tế.', 'Học bổng khuyến khích học tập, học bổng các công ty luật đa quốc gia (Baker McKenzie, YKVN, VILAF).', false, false),
  ('tdtu', 'truong-dai-hoc-ton-duc-thang', 'DTT', 'Trường Đại học Tôn Đức Thắng', 'ĐH Tôn Đức Thắng', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1997, 26000, 'Đại học chuẩn quốc tế QS 5 sao, tự chủ tài chính kiểu mẫu', 'https://tdtu.edu.vn', 'Đại học công lập tự chủ; cơ sở vật chất hiện đại, thế mạnh về CNTT, Kỹ thuật điện, Dược, Quản trị kinh doanh, Tài chính và Thiết kế công nghiệp.', 'Quỹ học bổng TDTU hàng chục tỷ đồng cho tân sinh viên xuất sắc và học bổng nghiên cứu khoa học.', false, false),
  ('iuh', 'truong-dai-hoc-cong-nghiep-tp-ho-chi-minh', 'HUI', 'Trường Đại học Công nghiệp TP. Hồ Chí Minh', 'ĐH Công nghiệp TP.HCM (IUH)', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1956, 35000, 'Đại học đạt chuẩn kiểm định quốc tế ABET & AUN-QA', 'https://iuh.edu.vn', 'Đào tạo kỹ sư ứng dụng đa ngành: Cơ khí, Điện tử, Tự động hóa, Ô tô, Hóa học, Thực phẩm, CNTT, Thương mại và Quản trị kinh doanh.', 'Học bổng khuyến khích học tập, học bổng doanh nghiệp đối tác Nhật Bản, Hàn Quốc.', false, false),
  ('ctu', 'truong-dai-hoc-can-tho', 'TCT', 'Trường Đại học Cần Thơ', 'ĐH Cần Thơ', 'cong-lap', 'nam', 'Cần Thơ', 1966, 45000, 'Đại học trọng điểm quốc gia lớn nhất vùng ĐBSCL', 'https://ctu.edu.vn', 'Đại học đa ngành lớn nhất Đồng bằng sông Cửu Long: CNTT, Nông nghiệp, Thủy sản, Môi trường, Kinh tế, Luật, Sư phạm và Kỹ thuật.', 'Học bổng khuyến khích học tập, học bổng tài trợ từ JICA Nhật Bản và các tổ chức quốc tế.', false, false),
  ('rmit', 'truong-dai-hoc-rmit-viet-nam', 'RMIT', 'Trường Đại học RMIT Việt Nam', 'RMIT Việt Nam', 'quoc-te', 'nam', 'TP. Hồ Chí Minh', 2000, 12000, 'Đại học quốc tế danh tiếng của Úc tại Việt Nam', 'https://rmit.edu.vn', 'Trường đại học 100% vốn nước ngoài hàng đầu; bằng cấp quốc tế công nhận toàn cầu trong các ngành Kinh doanh, Công nghệ, Truyền thông và Thiết kế số.', 'Học bổng Tổng hiệu trưởng 100% học phí, học bổng Tài năng, học bổng Công nghệ sáng tạo.', false, false),
  ('hutech', 'truong-dai-hoc-cong-nghe-tp-ho-chi-minh', 'HUTECH', 'Trường ĐH Công nghệ TP. Hồ Chí Minh', 'ĐH HUTECH', 'tu-thuc', 'nam', 'TP. Hồ Chí Minh', 1995, 30000, 'Đại học năng động, định hướng ứng dụng thực tế', 'https://hutech.edu.vn', 'Đào tạo đa ngành đa lĩnh vực: CNTT, Kỹ thuật ô tô, Quản trị kinh doanh, Marketing, Thiết kế thời trang, Truyền thông và Dược học.', 'Học bổng Doanh nghiệp, Học bổng Tài năng HUTECH trị giá từ 25% - 100% học phí.', false, false),
  ('vlu-sg', 'truong-dai-hoc-van-lang', 'VLU', 'Trường Đại học Văn Lang', 'ĐH Văn Lang', 'tu-thuc', 'nam', 'TP. Hồ Chí Minh', 1995, 28000, 'Cơ sở vật chất hiện đại, thế mạnh Thiết kế & Nghệ thuật', 'https://vlu.edu.vn', 'Đại học tư thục hàng đầu về Nghệ thuật & Thiết kế, Kiến trúc, Truyền thông đa phương tiện, Quan hệ công chúng, Y Dược và Quản trị khách sạn.', 'Quỹ học bổng Tài năng Văn Lang lên đến 100% toàn khóa học cho sinh viên xuất sắc.', false, false),
  ('hsu', 'truong-dai-hoc-hoa-sen', 'HSU', 'Trường Đại học Hoa Sen', 'ĐH Hoa Sen', 'tu-thuc', 'nam', 'TP. Hồ Chí Minh', 1991, 12000, 'Chuẩn quốc tế ACBSP (Hoa Kỳ) về khối Kinh doanh', 'https://hoasen.edu.vn', 'Mạnh về Quản trị khách sạn, Du lịch, Thiết kế đồ họa, Marketing, Kinh doanh quốc tế và Truyền thông giải trí.', 'Học bổng Tinh hoa Hoa Sen, học bổng Vượt khó lên đến 100% học phí.', false, false),
  ('cd-ckt', 'truong-cao-dang-ky-thuat-cao-thang', 'CD-CKT', 'Trường Cao đẳng Kỹ thuật Cao Thắng', 'CĐ Kỹ thuật Cao Thắng', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1906, 11000, 'Trường Cao đẳng kỹ thuật lâu đời & uy tín số 1 miền Nam', 'https://caothang.edu.vn', 'Trực thuộc Bộ Công Thương; đơn vị đào tạo kỹ thuật viên thực hành xuất sắc: Công nghệ Ô tô, Cơ khí CNC, Điện - Điện tử, Tự động hóa và CNTT với tỷ lệ việc làm trên 98%.', 'Học bổng khuyến khích nghề nghiệp, học bổng từ các tập đoàn công nghiệp đa quốc gia (Intel, Mitsubishi, Daikin).', false, false),
  ('cd-fpt-hcm', 'truong-cao-dang-fpt-polytechnic-tp-hcm', 'CD-FPTHCM', 'Trường Cao đẳng FPT Polytechnic TP.HCM', 'CĐ FPT Polytechnic TP.HCM', 'tu-thuc', 'nam', 'TP. Hồ Chí Minh', 2010, 20000, 'Thực học – Thực nghiệp, tỷ lệ việc làm 97.7%', 'https://caodang.fpt.edu.vn', 'Đào tạo thực hành kỹ năng số: Lập trình Web/App, Thiết kế đồ họa, Digital Marketing, Thương mại điện tử, Logistics và Công nghệ thông tin.', 'Học bổng khuyến học FPT Polytechnic, ưu đãi tân sinh viên.', false, false),
  ('cd-dlsg', 'truong-cao-dang-du-lich-sai-gon', 'CD-DLSG', 'Trường Cao đẳng Du lịch Sài Gòn', 'CĐ Du lịch Sài Gòn', 'tu-thuc', 'nam', 'TP. Hồ Chí Minh', 1991, 4500, 'Cái nôi nghề Du lịch & Khách sạn chất lượng cao', 'https://dulichsaigon.edu.vn', 'Chuyên sâu đào tạo Quản trị Khách sạn, Quản trị Lữ hành, Hướng dẫn du lịch quốc tế và Nghiệp vụ lễ tân - F&B.', 'Học bổng khuyến học du lịch, tài trợ tuyển dụng từ Saigontourist, Vietravel.', false, false),
  ('cd-ltt', 'truong-cao-dang-ly-tu-trong-tp-hcm', 'CD-LTT', 'Trường Cao đẳng Lý Tự Trọng TP.HCM', 'CĐ Lý Tự Trọng TP.HCM', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1986, 9000, 'Trường Cao đẳng công lập trọng điểm quốc gia', 'https://ltpct.edu.vn', 'Đào tạo đa ngành nghề thực hành: Công nghệ ô tô, Điện tử công nghiệp, Cơ điện tử, CNTT, Kế toán và Logistics.', 'Học bổng chính sách nhà nước, học bổng doanh nghiệp liên kết tuyển dụng.', false, false),
  ('cd-tdc', 'truong-cao-dang-cong-nghe-thu-duc', 'CD-TDC', 'Trường Cao đẳng Công nghệ Thủ Đức', 'CĐ Công nghệ Thủ Đức', 'cong-lap', 'nam', 'TP. Hồ Chí Minh', 1984, 8500, 'Trường Cao đẳng công nghệ kỹ thuật năng động tại TP. Thủ Đức', 'https://tdc.edu.vn', 'Đào tạo thực hành chuyên môn cao về Công nghệ thông tin, Thiết kế đồ họa, Quản trị mạng, Cơ khí chế tạo và Quản trị kinh doanh.', 'Học bổng khuyến khích học tập của UBND TP.HCM và các doanh nghiệp Khu công nghệ cao.', false, false);
