INSERT INTO majors (id, slug, code, name, group_id, summary, description, demand, growth, hidden, is_custom) VALUES
  ('cong-nghe-thong-tin', 'cong-nghe-thong-tin', '7480201', 'Công nghệ thông tin', 'cntt', 'Thiết kế, xây dựng và vận hành hệ thống phần mềm, mạng và dữ liệu cho doanh nghiệp.', 'Ngành Công nghệ thông tin trang bị nền tảng lập trình, cơ sở dữ liệu, mạng máy tính và kỹ năng phát triển sản phẩm số. Sinh viên được thực hành qua dự án thật từ năm 2–3.', 'Rất cao', 16, false, false),
  ('khoa-hoc-may-tinh', 'khoa-hoc-may-tinh', '7480101', 'Khoa học máy tính', 'cntt', 'Nền tảng toán – thuật toán cho phần mềm, trí tuệ nhân tạo và hệ thống thông minh.', 'Tập trung vào lý thuyết tính toán, thuật toán, học máy và hệ thống. Phù hợp với bạn thích toán và muốn làm nghiên cứu hoặc sản phẩm công nghệ lõi.', 'Rất cao', 18, false, false),
  ('ky-thuat-phan-mem', 'ky-thuat-phan-mem', '7480103', 'Kỹ thuật phần mềm', 'cntt', 'Quy trình chuyên nghiệp để phát triển, kiểm thử và vận hành phần mềm quy mô lớn.', 'Chú trọng quy trình phát triển phần mềm chuẩn quốc tế (Agile/Scrum, CI/CD, DevOps), kiến trúc phần mềm, kiểm thử và quản lý chất lượng dự án.', 'Rất cao', 15, false, false),
  ('tri-tue-nhan-tao', 'tri-tue-nhan-tao', '7480107', 'Trí tuệ nhân tạo', 'cntt', 'Xây dựng hệ thống tự học từ dữ liệu: học sâu, thị giác máy tính, AI tạo sinh và robot.', 'Ngành học mũi nhọn thời đại số đào tạo chuyên sâu về Machine Learning, Deep Learning, Generative AI và Robot thông minh ứng dụng trong đa lĩnh vực.', 'Rất cao', 24, false, false),
  ('khoa-hoc-du-lieu', 'khoa-hoc-du-lieu', '7480108', 'Khoa học dữ liệu', 'cntt', 'Khai phá dữ liệu lớn, phân tích thống kê và dự báo xu hướng kinh doanh bằng thuật toán.', 'Đào tạo các chuyên gia thu thập, xử lý và mô hình hóa dữ liệu (Big Data) để tìm ra thông tin giá trị giúp doanh nghiệp ra quyết định chiến lược.', 'Rất cao', 20, false, false),
  ('an-toan-thong-tin', 'an-toan-thong-tin', '7480202', 'An toàn thông tin', 'cntt', 'Bảo vệ hệ thống mạng, dữ liệu và hạ tầng công nghệ số khỏi các cuộc tấn công mạng.', 'Đào tạo các chuyên gia an ninh mạng có khả năng phòng thủ, phát hiện xâm nhập, điều tra số (Digital Forensics) và kiểm thử xâm nhập (Penetration Testing).', 'Rất cao', 19, false, false),
  ('he-thong-thong-tin', 'he-thong-thong-tin', '7480104', 'Hệ thống thông tin quản lý', 'cntt', 'Cầu nối giữa công nghệ và nghiệp vụ kinh doanh, thiết kế giải pháp số cho doanh nghiệp.', 'Đào tạo các chuyên viên phân tích nghiệp vụ (BA), phân tích hệ thống và triển khai các hệ thống số hóa quy trình quản trị doanh nghiệp.', 'Cao', 14, false, false),
  ('quan-tri-kinh-doanh', 'quan-tri-kinh-doanh', '7340101', 'Quản trị kinh doanh', 'kinh-te', 'Bao quát cách vận hành một tổ chức: từ chiến lược, nhân sự, tiếp thị đến tài chính.', 'Trang bị tư duy lãnh đạo, kỹ năng giải quyết vấn đề và năng lực điều hành doanh nghiệp trong môi trường cạnh tranh toàn cầu.', 'Cao', 12, false, false),
  ('marketing', 'marketing', '7340115', 'Marketing', 'kinh-te', 'Nghiên cứu thị trường, thấu hiểu khách hàng và xây dựng chiến dịch truyền thông quảng bá.', 'Đào tạo các nhà tiếp thị hiện đại kết hợp giữa thấu hiểu tâm lý người tiêu dùng, sáng tạo nội dung và đo lường hiệu quả bằng dữ liệu.', 'Rất cao', 17, false, false),
  ('kinh-doanh-quoc-te', 'kinh-doanh-quoc-te', '7340120', 'Kinh doanh quốc tế', 'kinh-te', 'Thương mại xuyên biên giới, xuất nhập khẩu, thanh toán quốc tế và chuỗi cung ứng toàn cầu.', 'Trang bị kiến thức về luật thương mại quốc tế, đàm phán hợp đồng ngoại thương, thủ tục hải quan và chiến lược thâm nhập thị trường nước ngoài.', 'Cao', 15, false, false),
  ('thuong-mai-dien-tu', 'thuong-mai-dien-tu', '7340122', 'Thương mại điện tử', 'kinh-te', 'Xây dựng và vận hành sàn thương mại điện tử, bán lẻ đa kênh Omni-channel và thanh toán số.', 'Kết hợp giữa tư duy kinh doanh và công nghệ internet để bán lẻ trực tuyến trên Shopee, TikTok Shop, Amazon và các nền tảng riêng.', 'Rất cao', 22, false, false),
  ('logistics-quan-ly-chuoi-cung-ung', 'logistics-quan-ly-chuoi-cung-ung', '7510605', 'Logistics và Quản lý chuỗi cung ứng', 'kinh-te', 'Tổ chức dòng lưu chuyển hàng hóa, kho bãi thông minh, vận tải đa phương thức và tối ưu chi phí.', 'Đào tạo các nhà quản lý chuỗi cung ứng đảm bảo hàng hóa được vận chuyển từ nơi sản xuất đến tay người tiêu dùng nhanh nhất với chi phí thấp nhất.', 'Rất cao', 18, false, false),
  ('tai-chinh-ngan-hang', 'tai-chinh-ngan-hang', '7340201', 'Tài chính – Ngân hàng', 'kinh-te', 'Quản trị dòng tiền, định giá tài sản, phân tích đầu tư chứng khoán và vận hành ngân hàng thương mại.', 'Đào tạo các chuyên gia tài chính ngân hàng có khả năng phân tích báo cáo tài chính, quản trị rủi ro tín dụng và ứng dụng công nghệ tài chính (Fintech).', 'Cao', 13, false, false),
  ('ke-toan', 'ke-toan', '7340301', 'Kế toán', 'kinh-te', 'Ghi chép, xử lý, lập báo cáo tài chính và quyết toán thuế theo chuẩn mực kế toán Việt Nam & quốc tế.', 'Ngành học nền tảng cho mọi tổ chức doanh nghiệp. Đào tạo kế toán viên thành thạo phần mềm kế toán MISA, FAST, SAP và chứng chỉ quốc tế ACCA, CPA.', 'Cao', 10, false, false),
  ('kiem-toan', 'kiem-toan', '7340302', 'Kiểm toán', 'kinh-te', 'Xác minh tính trung thực và hợp lý của báo cáo tài chính, kiểm soát nội bộ và chống gian lận.', 'Đào tạo các kiểm toán viên làm việc tại các hãng kiểm toán lớn Big 4 (PwC, Deloitte, EY, KPMG) và kiểm toán nội bộ doanh nghiệp.', 'Cao', 12, false, false),
  ('kinh-doanh-thuong-mai', 'kinh-doanh-thuong-mai', '7340121', 'Kinh doanh thương mại', 'kinh-te', 'Tổ chức mạng lưới phân phối bán buôn, bán lẻ, xúc tiến thương mại và quản trị ngành hàng.', 'Đào tạo các chuyên gia quản lý kênh phân phối (GT/MT), chuỗi siêu thị, đàm phán hợp đồng mua bán hàng hóa và phát triển thị trường tiêu dùng nhanh (FMCG).', 'Trung bình', 10, false, false),
  ('bao-hiem', 'bao-hiem', '7340203', 'Bảo hiểm', 'kinh-te', 'Định phí bảo hiểm, thẩm định rủi ro, bồi thường thiệt hại và tư vấn giải pháp an toàn tài chính.', 'Đào tạo các chuyên gia định phí bảo hiểm (Actuary), thẩm định viên bồi thường và quản lý kinh doanh bảo hiểm nhân thọ, phi nhân thọ.', 'Trung bình', 11, false, false),
  ('quan-tri-du-lich', 'quan-tri-du-lich', '7810103', 'Quản trị dịch vụ du lịch và lữ hành', 'kinh-te', 'Thiết kế tour, điều hành hướng dẫn viên, quản lý chuỗi khách sạn – resort và sự kiện hội nghị (MICE).', 'Đào tạo các nhà quản lý dịch vụ hiếu khách (Hospitality), điều hành tour du lịch trong nước & quốc tế với kỹ năng giao tiếp và ngoại ngữ lưu loát.', 'Cao', 16, false, false),
  ('ky-thuat-dien', 'ky-thuat-dien', '7520201', 'Kỹ thuật Điện – Điện tử', 'ky-thuat', 'Hệ thống truyền tải điện năng, trạm biến áp, máy điện và mạch điện tử công suất lớn.', 'Đào tạo các kỹ sư thiết kế mạng lưới điện quốc gia, năng lượng tái tạo (điện gió, điện mặt trời) và các hệ thống điều khiển điện tử công nghiệp.', 'Cao', 14, false, false),
  ('ky-thuat-co-khi', 'ky-thuat-co-khi', '7520103', 'Kỹ thuật Cơ khí', 'ky-thuat', 'Thiết kế máy móc, gia công cơ khí chính xác CNC, chế tạo thiết bị công nghiệp và khuôn mẫu.', 'Đào tạo các kỹ sư cơ khí thành thạo phần mềm thiết kế 3D SolidWorks, NX, Mastercam và vận hành máy công cụ CNC hiện đại.', 'Cao', 12, false, false),
  ('ky-thuat-co-dien-tu', 'ky-thuat-co-dien-tu', '7520114', 'Kỹ thuật Cơ điện tử', 'ky-thuat', 'Sự kết hợp liên ngành giữa Cơ khí chính xác, Điện tử điều khiển và Lập trình nhúng thông minh.', 'Đào tạo các kỹ sư thiết kế robot công nghiệp, máy bay không người lái (drone), hệ thống tay gắp thông minh và dây chuyền tự động hóa thế hệ mới.', 'Rất cao', 18, false, false),
  ('ky-thuat-dieu-khien-va-tu-dong-hoa', 'ky-thuat-dieu-khien-va-tu-dong-hoa', '7520216', 'Kỹ thuật Điều khiển và Tự động hóa', 'ky-thuat', 'Lập trình PLC, hệ thống giám sát SCADA/DCS và tối ưu hóa dây chuyền sản xuất tự động 24/7.', 'Đào tạo các kỹ sư điều khiển lập trình các bộ điều khiển công nghiệp PLC Siemens, Mitsubishi, Rockwell để vận hành các nhà máy tự động hóa hoàn toàn.', 'Rất cao', 16, false, false),
  ('ky-thuat-o-to', 'ky-thuat-o-to', '7520130', 'Kỹ thuật Ô tô', 'ky-thuat', 'Nghiên cứu động cơ đốt trong, xe điện (EV), hệ thống truyền lực, chẩn đoán lỗi và an toàn ô tô.', 'Đào tạo các kỹ sư có khả năng thiết kế khung gầm ô tô, nghiên cứu hệ thống pin và điều khiển xe điện thông minh của các hãng lớn.', 'Rất cao', 19, false, false),
  ('ky-thuat-xay-dung', 'ky-thuat-xay-dung', '7580201', 'Kỹ thuật Xây dựng', 'ky-thuat', 'Tính toán kết cấu bê tông cốt thép, nền móng, thi công cầu đường và quản lý dự án công trình.', 'Đào tạo các kỹ sư xây dựng thành thạo phần mềm tính kết cấu Etabs, SAP2000, mô hình thông tin công trình BIM (Revit) và chỉ huy thi công hiện trường.', 'Cao', 11, false, false),
  ('kien-truc', 'kien-truc', '7580101', 'Kiến trúc', 'nghe-thuat', 'Sáng tạo không gian sống, thiết kế hình khối công trình thẩm mỹ và hòa hợp công năng sử dụng.', 'Ngành học kết hợp giữa nghệ thuật và kỹ thuật. Đào tạo các kiến trúc sư có tư duy không gian xuất sắc, làm chủ các công cụ AutoCAD, SketchUp, 3ds Max, Enscape.', 'Cao', 13, false, false),
  ('quy-hoach-do-thi', 'quy-hoach-do-thi', '7580105', 'Quy hoạch vùng và đô thị', 'ky-thuat', 'Quy hoạch phân khu chức năng thành phố, hạ tầng giao thông đô thị và phát triển thành phố thông minh.', 'Đào tạo các kỹ sư quy hoạch không gian đô thị sử dụng phần mềm GIS, bản đồ số để thiết kế các khu đô thị mới hiện đại và sinh thái.', 'Trung bình', 11, false, false),
  ('thiet-ke-vi-mach-ban-dan', 'thiet-ke-vi-mach-ban-dan', '7520202', 'Thiết kế Vi mạch & Bán dẫn', 'ky-thuat', 'Thiết kế chip bán dẫn, vi mạch số/tương tự (IC), kiểm thử wafer và đóng gói linh kiện bán dẫn.', 'Ngành công nghệ chiến lược quốc gia đào tạo kỹ sư thiết kế chip trên công cụ Synopsys, Cadence đáp ứng nhu cầu khổng lồ từ Nvidia, Qualcomm, Intel, Synopsys.', 'Rất cao', 25, false, false),
  ('ky-thuat-hoa-hoc', 'ky-thuat-hoa-hoc', '7520301', 'Kỹ thuật Hóa học', 'ky-thuat', 'Công nghệ lọc hóa dầu, sản xuất polymer, vật liệu nano, dược phẩm và mỹ phẩm công nghiệp.', 'Đào tạo các kỹ sư hóa học vận hành các tháp chưng cất, phản ứng hóa học công nghiệp và kiểm nghiệm chất lượng sản phẩm trong phòng thí nghiệm hiện đại.', 'Trung bình', 11, false, false),
  ('ky-thuat-moi-truong', 'ky-thuat-moi-truong', '7520320', 'Kỹ thuật Môi trường', 'ky-thuat', 'Xử lý nước thải công nghiệp, khí thải, rác thải nguy hại và đánh giá tác động môi trường (ĐTM).', 'Đào tạo các kỹ sư thiết kế các trạm xử lý nước cấp, nước thải sinh hoạt/công nghiệp và lập báo cáo quan trắc môi trường cho doanh nghiệp.', 'Trung bình', 12, false, false),
  ('cong-nghe-thuc-pham', 'cong-nghe-thuc-pham', '7540101', 'Công nghệ thực phẩm', 'ky-thuat', 'Bảo quản, chế biến đồ hộp, bánh kẹo, đồ uống và kiểm định vệ sinh an toàn thực phẩm.', 'Đào tạo các kỹ sư phát triển công thức đồ uống, thực phẩm chức năng và kiểm soát chất lượng theo tiêu chuẩn HACCP, ISO 22000.', 'Cao', 14, false, false),
  ('khoa-hoc-moi-truong', 'khoa-hoc-moi-truong', '7440301', 'Khoa học Môi trường', 'ky-thuat', 'Quan trắc sinh thái, phân tích ô nhiễm đất – nước – không khí và giải pháp biến đổi khí hậu.', 'Đào tạo các nhà khoa học môi trường có khả năng lấy mẫu, đo đạc chất lượng môi trường trong phòng thí nghiệm và xây dựng chính sách giảm thiểu phát thải.', 'Trung bình', 15, false, false),
  ('y-khoa', 'y-khoa', '7720101', 'Y khoa (Bác sĩ Đa khoa)', 'y-duoc', 'Chẩn đoán, điều trị, phẫu thuật và chăm sóc sức khỏe toàn diện cho người bệnh.', 'Chương trình đào tạo 6 năm khắt khe. Sinh viên học lý thuyết y học cơ sở kết hợp đi thực tập lâm sàng tại các bệnh viện tuyến trung ương từ năm 3.', 'Rất cao', 16, false, false),
  ('duoc-hoc', 'duoc-hoc', '7720201', 'Dược học (Dược sĩ)', 'y-duoc', 'Bào chế thuốc, nghiên cứu dược lý, kiểm nghiệm chất lượng và dược lâm sàng tại bệnh viện.', 'Đào tạo các Dược sĩ Đại học (5 năm) có quyền cấp chứng chỉ hành nghề, mở nhà thuốc, làm việc tại công ty dược đa quốc gia và bệnh viện.', 'Rất cao', 15, false, false),
  ('rang-ham-mat', 'rang-ham-mat', '7720501', 'Răng – Hàm – Mặt (Bác sĩ Nha khoa)', 'y-duoc', 'Khám chữa bệnh răng miệng, niềng răng thẩm mỹ, cấy ghép Implant và phẫu thuật hàm mặt.', 'Chương trình 6 năm đào tạo Bác sĩ Răng Hàm Mặt thực hành trên mô hình nha khoa hiện đại và bệnh nhân thật tại viện trường.', 'Rất cao', 18, false, false),
  ('dieu-duong', 'dieu-duong', '7720301', 'Điều dưỡng', 'y-duoc', 'Thực hiện y lệnh bác sĩ, theo dõi dấu hiệu sinh tồn, chăm sóc và phục hồi chức năng cho bệnh nhân.', 'Đào tạo các điều dưỡng viên có tay nghề vững vàng, tận tâm, có cơ hội làm việc tại các bệnh viện lớn trong nước và xuất khẩu sang Đức, Nhật Bản.', 'Rất cao', 20, false, false),
  ('luat', 'luat', '7380101', 'Luật', 'xa-hoi', 'Hệ thống pháp luật, tranh tụng tại tòa án, tư vấn pháp lý dân sự, hình sự và thương mại.', 'Đào tạo các cử nhân luật có tư duy phản biện sắc bén, hiểu sâu hệ thống văn bản quy phạm pháp luật và kỹ năng soạn thảo hợp đồng, bào chữa.', 'Cao', 12, false, false),
  ('luat-kinh-te', 'luat-kinh-te', '7380107', 'Luật Kinh tế', 'xa-hoi', 'Pháp luật về doanh nghiệp, hợp đồng thương mại, sáp nhập mua bán (M&A) và sở hữu trí tuệ.', 'Chuyên sâu về các quy định pháp lý trong hoạt động đầu tư, chứng khoán, ngân hàng, bảo vệ quyền lợi của doanh nghiệp trước pháp luật.', 'Cao', 14, false, false),
  ('quan-he-quoc-te', 'quan-he-quoc-te', '7310206', 'Quan hệ quốc tế', 'xa-hoi', 'Ngoại giao nhà nước, chính sách đối ngoại, tổ chức phi chính phủ (NGO) và quan hệ đa phương.', 'Đào tạo các nhà ngoại giao tương lai với kiến thức sâu rộng về địa chính trị thế giới, lễ tân ngoại giao và kỹ năng thương thuyết quốc tế.', 'Trung bình', 12, false, false),
  ('truyen-thong-da-phuong-tien', 'truyen-thong-da-phuong-tien', '7320104', 'Truyền thông đa phương tiện', 'xa-hoi', 'Sản xuất video, podcast, đồ họa tương tác, quản trị nội dung mạng xã hội và kỹ xảo kỹ thuật số.', 'Đào tạo các nhà sáng tạo nội dung đa năng (Content Creator), đạo diễn hình ảnh, dựng phim và quản lý các kênh YouTube, TikTok, Facebook.', 'Rất cao', 21, false, false),
  ('quan-he-cong-chung', 'quan-he-cong-chung', '7320103', 'Quan hệ công chúng (PR)', 'xa-hoi', 'Xây dựng hình ảnh doanh nghiệp, tổ chức họp báo, quan hệ báo chí và xử lý khủng hoảng truyền thông.', 'Đào tạo các chuyên gia PR kết nối thông tin giữa tổ chức với công chúng, cơ quan báo chí, người nổi tiếng (KOL/KOC) và cổ đông.', 'Cao', 16, false, false),
  ('bao-chi', 'bao-chi', '7320101', 'Báo chí', 'xa-hoi', 'Thu thập tin tức, phỏng vấn, điều tra sự thật, viết phóng sự báo in, báo điện tử và truyền hình.', 'Đào tạo các nhà báo có đạo đức nghề nghiệp, bản lĩnh điều tra, kỹ năng phỏng vấn sắc sảo và sản xuất báo chí dữ liệu hiện đại (Data Journalism).', 'Trung bình', 10, false, false),
  ('tam-ly-hoc', 'tam-ly-hoc', '7310401', 'Tâm lý học', 'xa-hoi', 'Nghiên cứu hành vi con người, tư vấn tham vấn tâm lý học đường, gia đình và trị liệu tâm lý.', 'Đào tạo các chuyên gia tâm lý thấu hiểu cảm xúc, đánh giá rối loạn tâm lý (trầm cảm, lo âu) và trị liệu tâm lý theo phương pháp khoa học.', 'Cao', 19, false, false),
  ('ngon-ngu-anh', 'ngon-ngu-anh', '7220201', 'Ngôn ngữ Anh', 'xa-hoi', 'Thành thạo tiếng Anh học thuật C1-C2, biên phiên dịch cabin, giảng dạy và tiếng Anh thương mại.', 'Đào tạo các cử nhân có khả năng dịch thuật văn bản ngoại giao, hợp đồng kinh tế và giảng dạy tiếng Anh chuẩn quốc tế IELTS, TESOL.', 'Cao', 13, false, false),
  ('ngoai-ngu-anh', 'ngoai-ngu-anh', '7220201', 'Ngôn ngữ Anh', 'xa-hoi', 'Thành thạo tiếng Anh học thuật C1-C2, biên phiên dịch cabin, giảng dạy và tiếng Anh thương mại.', 'Đào tạo các cử nhân có khả năng dịch thuật văn bản ngoại giao, hợp đồng kinh tế và giảng dạy tiếng Anh chuẩn quốc tế IELTS, TESOL.', 'Cao', 13, false, false),
  ('ngoai-ngu-nhat', 'ngoai-ngu-nhat', '7220209', 'Ngôn ngữ Nhật', 'xa-hoi', 'Thành thạo tiếng Nhật chuẩn N2-N1, văn hóa doanh nghiệp Nhật (Omotenashi) và biên phiên dịch IT (Comtor).', 'Đào tạo các cử nhân tiếng Nhật làm việc tại các công ty Nhật Bản (FDI), kỹ sư cầu nối IT (BrSE) và thông dịch viên nhà máy.', 'Rất cao', 17, false, false),
  ('ngoai-ngu-trung', 'ngoai-ngu-trung', '7220204', 'Ngôn ngữ Trung Quốc', 'xa-hoi', 'Thành thạo tiếng Trung chuẩn HSK 5-6, thương mại xuyên biên giới Trung – Việt và dịch thuật du lịch.', 'Đào tạo các cử nhân tiếng Trung am hiểu thị trường tỷ dân Trung Quốc, phục vụ nhu cầu thông dịch khổng lồ của các nhà máy FDI và sàn TMĐT Taobao, 1688.', 'Rất cao', 19, false, false),
  ('thiet-ke-do-hoa', 'thiet-ke-do-hoa', '7210403', 'Thiết kế đồ họa', 'nghe-thuat', 'Bộ nhận diện thương hiệu, thiết kế bao bì, giao diện UI/UX và minh họa kỹ thuật số (Digital Art).', 'Đào tạo các nhà thiết kế đồ họa có tư duy thẩm mỹ cao, làm chủ bộ công cụ Adobe Creative Cloud (Photoshop, Illustrator, InDesign, Figma) và 3D Blender.', 'Rất cao', 17, false, false),
  ('thiet-ke-noi-that', 'thiet-ke-noi-that', '7580108', 'Thiết kế nội thất', 'nghe-thuat', 'Bố trí không gian nội thất căn hộ, biệt thự, showroom, vật liệu gỗ và ánh sáng trang trí.', 'Đào tạo các nhà thiết kế không gian nội thất biết cách biến những căn phòng thô thành không gian sống tiện nghi, sang trọng qua 3ds Max, Corona Render.', 'Cao', 14, false, false),
  ('su-pham-toan', 'su-pham-toan', '7140209', 'Sư phạm Toán học', 'giao-duc', 'Phương pháp giảng dạy Toán cấp THCS – THPT, bồi dưỡng học sinh giỏi và toán ứng dụng.', 'Đào tạo các giáo viên dạy Toán có kiến thức chuyên sâu, phương pháp sư phạm hiện đại, ứng dụng GeoGebra và công nghệ số vào bài giảng.', 'Cao', 11, false, false),
  ('su-pham-toan-hoc', 'su-pham-toan-hoc', '7140209', 'Sư phạm Toán học', 'giao-duc', 'Phương pháp giảng dạy Toán cấp THCS – THPT, bồi dưỡng học sinh giỏi và toán ứng dụng.', 'Đào tạo các giáo viên dạy Toán có kiến thức chuyên sâu, phương pháp sư phạm hiện đại.', 'Cao', 11, false, false),
  ('su-pham-tieng-anh', 'su-pham-tieng-anh', '7140231', 'Sư phạm Tiếng Anh', 'giao-duc', 'Phương pháp giảng dạy tiếng Anh chuẩn quốc tế (TESOL/CELTA), thiết kế giáo trình và khảo thí ngôn ngữ.', 'Đào tạo các giáo viên tiếng Anh tài năng cho các trường THCS, THPT chuyên và các hệ thống trường song ngữ quốc tế.', 'Rất cao', 16, false, false),
  ('thu-y', 'thu-y', '7640101', 'Thú y (Bác sĩ Thú y)', 'nong-lam', 'Chẩn đoán, phẫu thuật, tiêm phòng cho thú cưng (chó, mèo) và kiểm soát dịch bệnh đàn gia súc, gia cầm.', 'Đào tạo các Bác sĩ Thú y (5 năm) có khả năng khám chữa bệnh tại các bệnh viện thú cưng hiện đại hoặc quản lý sức khỏe đàn vật nuôi quy mô trang trại lớn.', 'Rất cao', 22, false, false),
  ('nong-nghiep-cong-nghe-cao', 'nong-nghiep-cong-nghe-cao', '7620101', 'Nông nghiệp công nghệ cao', 'nong-lam', 'Trồng trọt nhà màng thông minh, nông nghiệp chính xác IoT, thủy canh hồi lưu và giống cây biến đổi gen.', 'Đào tạo các kỹ sư làm chủ công nghệ điều khiển khí hậu nhà kính tự động bằng cảm biến, drone phun thuốc và sản xuất rau quả sạch đạt chuẩn xuất khẩu.', 'Cao', 15, false, false);
