INSERT INTO major_curriculum_items (block_id, name, description, position) SELECT b.id, x.name, x.description, x.position FROM b, (VALUES ('Cấu trúc dữ liệu & giải thuật', 'Tư duy giải quyết bài toán và tối ưu chương trình.', 1), ('Cơ sở dữ liệu', 'Thiết kế, truy vấn và quản trị dữ liệu quan hệ.', 2)) AS x(name, description, position);
INSERT INTO major_curriculum_items (block_id, name, description, position) SELECT b.id, x.name, x.description, x.position FROM b, (VALUES ('Phát triển ứng dụng web & di động', 'Front-end, back-end và triển khai trên đám mây.', 1), ('An toàn thông tin', 'Bảo mật hệ thống, mạng và ứng dụng.', 2)) AS x(name, description, position);
INSERT INTO major_curriculum_items (block_id, name, description, position) SELECT b.id, x.name, x.description, x.position FROM b, (VALUES ('Toán rời rạc & Đại số tuyến tính', 'Logic, đồ thị, tổ hợp cho khoa học máy tính và AI.', 1), ('Kiến trúc máy tính & Hệ điều hành', 'Cách phần cứng thực thi chương trình và quản lý bộ nhớ.', 2)) AS x(name, description, position);
INSERT INTO major_curriculum_items (block_id, name, description, position) SELECT b.id, x.name, x.description, x.position FROM b, (VALUES ('Học máy (Machine Learning)', 'Mô hình dự đoán, phân loại và nhận diện từ dữ liệu.', 1), ('Hệ thống tính toán hiệu năng cao', 'Tính toán song song trên GPU và cụm máy chủ phân tán.', 2)) AS x(name, description, position);
INSERT INTO major_curriculum_items (block_id, name, description, position) SELECT b.id, x.name, x.description, x.position FROM b, (VALUES ('Lập trình hướng đối tượng (OOP)', 'Thiết kế mẫu (Design Patterns), viết mã sạch và dễ bảo trì.', 1), ('Phân tích & thiết kế hệ thống', 'Mô hình hoá yêu cầu bằng UML và thiết kế cơ sở dữ liệu.', 2)) AS x(name, description, position);
